# Exercise the historical CLI only with files generated by this test.
if (length(commandArgs(trailingOnly = TRUE)) != 0L) {
  stop("This test takes no input or output arguments.", call. = FALSE)
}
Sys.umask("0077")
script_arg <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
stopifnot(length(script_arg) == 1L)
root <- dirname(dirname(normalizePath(sub("^--file=", "", script_arg), mustWork = TRUE)))
runner <- file.path(root, "R", "e1", "aim1_e1_nb_assumption_runner.R")
rscript <- file.path(R.home("bin"), "Rscript")
stopifnot(file.exists(runner), file.exists(rscript))
for (package in c("MASS", "jsonlite")) {
  if (!requireNamespace(package, quietly = TRUE)) {
    stop(sprintf("Missing R package: %s", package), call. = FALSE)
  }
}

fixture_dir <- tempfile("e1-synthetic-")
stopifnot(dir.create(fixture_dir, mode = "0700"))
set.seed(419L)
# The frozen runner requires the historical schema width and 527 roster rows.
i <- seq_len(527L)
eligible <- i <= 180L
score <- stats::runif(length(i), 0.1, 0.8)
age <- sample(55:85, length(i), replace = TRUE)
sex <- sample(c("F", "M"), length(i), replace = TRUE)
days <- sample(365:2500, length(i), replace = TRUE)
years <- days / 365.25
dp <- stats::rnbinom(length(i), size = 0.8, mu = years * exp(0.2 + score))
fixture <- data.frame(
  row_id = paste0("row", i),
  status = ifelse(eligible, "ELIGIBLE", "SEX_UNRESOLVED"),
  deac20 = score,
  age_index = age,
  sex_encoded_in_bridge_hetu = sex,
  person_days = days,
  person_years = years,
  R_P = dp + 1L,
  D_P = dp,
  R_A = dp + 3L,
  D_A = dp + 1L
)
fixture[!eligible, -(1:2)] <- NA

run_fixture <- function(data, label) {
  input <- file.path(fixture_dir, paste0(label, ".csv"))
  output <- file.path(fixture_dir, paste0(label, ".json"))
  utils::write.csv(data, input, row.names = FALSE, na = "")
  status <- system2(rscript, c("--vanilla", shQuote(c(runner, input, output))))
  list(status = status, output = output)
}

valid <- run_fixture(fixture, "valid")
stopifnot(valid$status == 0L, file.exists(valid$output))
report <- jsonlite::fromJSON(valid$output, simplifyVector = FALSE)
outcomes <- c("R_P", "D_P", "R_A", "D_A")
stopifnot(
  identical(report$schema, "aim1-e1-nb-model-results-v1"),
  identical(report$status, "FOUR_MODELS_ESTIMATED"),
  identical(names(report$models), outcomes),
  report$source_people == nrow(fixture),
  report$model_eligible_n == sum(eligible),
  report$model_status_counts$SEX_UNRESOLVED == sum(!eligible),
  isTRUE(all.equal(report$total_person_years, sum(years[eligible]))),
  identical(
    report$model_formula,
    paste0("count ~ deac20/0.1 + age_index + ", "sex_encoded_in_bridge_hetu + offset(log(person_years))")
  )
)
for (outcome in outcomes) {
  model <- report$models[[outcome]]
  expected_unit <- if (startsWith(outcome, "D_")) "PERSON_DAY_PROXY" else "SOURCE_ROW_PROXY"
  stopifnot(
    identical(model$status, "ESTIMATED"),
    identical(model$response_unit, expected_unit),
    model$n == sum(eligible),
    model$count_sum == sum(fixture[[outcome]][eligible]),
    length(model$ci95_wald) == 2L,
    is.finite(model$irr_per_0_1), model$irr_per_0_1 > 0,
    model$ci95_wald[[1L]] <= model$irr_per_0_1,
    model$irr_per_0_1 <= model$ci95_wald[[2L]],
    identical(model$diagnostic$status, "COMPUTED")
  )
}

for (case in c("missing_sex", "invalid_sex", "short_input")) {
  candidate <- fixture
  if (case == "short_input") {
    candidate <- candidate[1:12, , drop = FALSE]
  } else {
    candidate$sex_encoded_in_bridge_hetu[1L] <- if (case == "missing_sex") NA else "invalid"
  }
  rejected <- run_fixture(candidate, case)
  stopifnot(rejected$status == 2L, !file.exists(rejected$output))
}
cat("E1 synthetic CLI: 4/4 cases passed (four models and three input rejections).\n")
